// Original code-native screen artwork. Generated data dedicated under CC0-1.0.
// Reads only the font generated by our own generator, never upstream game assets.
import {mkdir,readFile,writeFile} from 'node:fs/promises';
import {resolve} from 'node:path';
import {createHash} from 'node:crypto';
import {encodePlanar} from './lib/supaplex-planar.mjs';
const out=resolve(process.argv[2]||'.cache/open-screens');await mkdir(out,{recursive:true});
const font=await readFile('.cache/open-font/CHARS6.DAT');
if(createHash('sha256').update(font).digest('hex')!=='f1ad9b07226ad98a27fec6f26182b15dde71fb73625660876887c60fe0ad37df')throw Error('Regenerate the original font first');
const colors=['101722','8995a8','223851','397faf','51c4d5','75e5d1','ffc36b','ed805e','485c73','7994b5','e3f2ff','ff718c','956ed9','cadc81','69a2fa','ffffff'];
const files=[];
async function save(name,bytes){await writeFile(resolve(out,name),bytes);files.push({name,bytes:bytes.length,sha256:createHash('sha256').update(bytes).digest('hex')});}
const palette=new Uint8Array(256);
for(let group=0;group<4;group++)for(let i=0;i<16;i++) {
  for(let c=0;c<3;c++)palette[group*64+i*4+c]=parseInt(colors[i].slice(c*2,c*2+2),16)>>4;
  palette[group*64+i*4+3]=15;
}
await save('PALETTES.DAT',palette);
for(const name of ['MENU','BACK','CONTROLS','GFX','TITLE','TITLE1','TITLE2','PANEL']) {
  const height=name==='PANEL'?24:200,pixels=new Uint8Array(320*height);
  const rect=(x,y,w,h,c)=>{for(let yy=y;yy<y+h;yy++)for(let xx=x;xx<x+w;xx++)if(xx>=0&&xx<320&&yy>=0&&yy<height)pixels[yy*320+xx]=c;};
  const text=(s,x,y,c=10)=>{for(let i=0;i<s.length;i++){const code=s.charCodeAt(i)-32;if(code<0||code>=64)throw Error('Unsupported text');for(let yy=0;yy<8;yy++)for(let xx=0;xx<6;xx++)if(font[yy*64+code]&(128>>xx))rect(x+i*6+xx,y+yy,1,1,c);}};
  const button=(s,x,y,w,h)=>{rect(x,y,w,h,2);rect(x,y,w,1,3);text(s,x+2,y+Math.floor((h-8)/2));};
  if(name==='MENU') {
    ['NEW PLAYER','DELETE PLAYER','SKIP LEVEL','STATISTICS','TILE GUIDE','DEMOS','CONTROLS'].forEach((s,i)=>button(s,5,6+i*9,152,8));
    text('OPEN PATHS',179,12,5);text('ASSET PROTOTYPE',171,23,9);
    button('?',297,37,15,15);button('^',140,90,15,18);button('V',140,121,15,17);
    button('GO',96,140,19,23);button('PACK',83,168,43,24);
    button('UP',11,142,56,11);button('DOWN',11,181,56,11);
    button('PREVIOUS',142,142,164,11);button('NEXT',142,181,164,11);
  } else if(name==='PANEL') {
    rect(0,0,320,1,3);text('OPEN PATHS',4,2,5);text('ESC: MENU',238,2,9);
  } else if(name==='CONTROLS') {
    text('CONTROLS',30,25,5);text('ARROWS: MOVE',30,50);text('SPACE: ACTION',30,65);text('ESC: RETURN TO MENU',30,80);text('REPLACEMENT PACK IN DEVELOPMENT',30,160,9);
  } else if(name==='GFX') {
    text('TILE GUIDE',30,25,5);text('ROVER: YOUR CHARACTER',30,55);text('DOTTED BASE: WALK THROUGH',30,70);text('FRAMED ARROW: EXIT',30,85);text('WALL: BLOCKED',30,100);
  } else if(name.startsWith('TITLE')) {
    rect(35,45,250,100,2);rect(35,45,250,2,4);text('OPEN PATHS',124,65,5);
    text('ORIGINAL REPLACEMENT DATA',88,90);text('SUPAPLEX ENGINE EXPERIMENT',82,106,9);text('PRESS ENTER',127,130,10);
  }
  await save(name+'.DAT',encodePlanar(pixels,320,height));
  // Exact vector preview of the indexed pixels; no screenshot or copied reference artwork.
  const rectangles=[];for(let y=0;y<height;y++)for(let x=0;x<320;x++){const c=pixels[y*320+x];if(c)rectangles.push(`<rect x="${x}" y="${y}" width="1" height="1" fill="#${colors[c]}"/>`);}
  await writeFile(resolve(out,name.toLowerCase()+'.svg'),`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 ${height}" width="960" height="${height*3}"><rect width="320" height="${height}" fill="#${colors[0]}"/>${rectangles.join('')}</svg>`);
}
await writeFile(resolve(out,'manifest.json'),JSON.stringify({license:'CC0-1.0',originalAssetsUsed:false,engineTested:false,limitations:['Engine title palettes still need replacement','Menu layout uses engine hit regions but has not been visually tested','No moving sprites, campaign packaging, demos, or sound assets'],files},null,2)+'\n');
console.log('Generated original screen prototypes and four runtime palettes; not an integrated release.');
